//! Shared helper for the Lifecycle-gate integration tests: builds a `SupervisorConfig`
//! pointing at a fresh copy of the `fake-tsc` binary inside a `node_modules/typescript/
//! bin/` layout, so `check_version`'s `package.json` lookup finds a real, matching
//! version rather than needing every test to fake that out itself.
//!
//! Each `tests/*.rs` file compiles this module separately as its own crate, so a
//! helper unused by one particular test binary is expected, not a real dead-code
//! finding — hence the blanket allow below.
#![allow(dead_code)]

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::SupervisorConfig;

pub const PINNED_VERSION: &str = "7.1.0-test";

/// Returns the temp dir (kept alive for the caller's test duration) and a config ready
/// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
    let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
    let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
    let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
    config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
    (dir, config)
}

/// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
/// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
/// `(tsc_path, cwd)`.
pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    let bin_dir = typescript_dir.join("bin");
    std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");

    let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
    let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");

    (
        Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}

/// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
/// case.
pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");
    let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    (
        Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}
mod common;

use std::time::Duration;

use oxc_react_docgen_tsc_client::{Supervisor, TscClientError};

#[tokio::test]
async fn a_process_that_crashes_on_every_restart_gives_up_after_the_cap() {
    // Crashes immediately on every spawn, including every respawn attempt — drives
    // the supervisor's bounded restart policy to exhaustion.
    let (_dir, config) = common::spawn_fake("crash_immediately:9");
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    // First call: the crashed process answers nothing, restart is attempted and the
    // freshly-restarted process also crashes immediately, so the retried call also
    // fails — this consumes one restart attempt per call until the cap trips.
    let mut storm_detected = false;
    for _ in 0..10 {
        match supervisor.request("ping", serde_json::json!({}), Duration::from_secs(2)).await {
            Err(TscClientError::RestartStormDetected { .. }) => {
                storm_detected = true;
                break;
            }
            _ => continue,
        }
    }

    assert!(storm_detected, "expected RestartStormDetected within 10 calls, restart cap never tripped");

    // Once tripped, the supervisor short-circuits every further call without touching
    // the process again.
    match supervisor.request("ping", serde_json::json!({}), Duration::from_secs(2)).await {
        Err(TscClientError::RestartStormDetected { .. }) => {}
        other => panic!("expected the supervisor to stay permanently failed, got {other:?}"),
    }
}
mod common;

use std::time::Duration;

use oxc_react_docgen_tsc_client::{Client, TscClientError};

#[tokio::test]
async fn a_process_that_exits_mid_session_fails_the_next_request_as_crashed() {
    // Answers the first request, then exits — a second request gets no response.
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = oxc_react_docgen_tsc_client::Supervisor::spawn(config).await.expect("spawn fake tsc");

    let first = supervisor.request("first", serde_json::json!({}), Duration::from_secs(2)).await;
    assert!(first.is_ok(), "expected the first request to succeed, got {first:?}");

    // The second request may report Crashed directly, or (since Supervisor::request
    // auto-restarts once on Crashed) succeed against the restarted process — both are
    // correct; what matters is it isn't left hanging or silently wrong. Use the
    // low-level Client directly instead, which never restarts, to observe the crash
    // itself deterministically.
    let raw_client: Client = supervisor.client();
    // Give the crashed process's reader task a moment to notice EOF.
    tokio::time::sleep(Duration::from_millis(100)).await;
    let second = raw_client.request("second", serde_json::json!({}), Duration::from_secs(2)).await;
    match second {
        // Whether the crash surfaces as `Crashed` (reader task noticed EOF first) or
        // `Write` (the stdin pipe was already closed) is a timing race, not something
        // this crate controls — both mean the same thing: the process is gone.
        Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) => {}
        Err(other) => panic!("expected Crashed or Write, got {other:?}"),
        Ok(response) => panic!("expected an error, got a response: {response:?}"),
    }
}
mod common;

use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};

#[tokio::test]
async fn spawning_a_nonexistent_binary_reports_spawn_failed() {
    let dir = tempfile::tempdir().expect("temp dir");
    let (tsc_path, cwd) = common::layout_without_binary(&dir, common::PINNED_VERSION);
    let config = SupervisorConfig::new(tsc_path, cwd, &[common::PINNED_VERSION]);

    match Supervisor::spawn(config).await {
        Err(TscClientError::SpawnFailed { .. }) => {}
        Err(other) => panic!("expected SpawnFailed, got {other:?}"),
        Ok(_) => panic!("expected SpawnFailed, but spawn succeeded"),
    }
}
mod common;

use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};

#[tokio::test]
async fn a_version_not_in_the_pinned_list_is_rejected_before_spawning() {
    let dir = tempfile::tempdir().expect("temp dir");
    // Layout carries a real tsc binary at a real version, but the config pins a
    // different one — check_version must reject it without ever spawning the process
    // (the fake binary would otherwise happily talk to us).
    let (tsc_path, cwd) = common::layout_with_version(&dir, "6.0.0");
    let config = SupervisorConfig::new(tsc_path, cwd, &["7.1.0-dev.20260926.1"]);

    match Supervisor::spawn(config).await {
        Err(TscClientError::UnsupportedVersion { found, expected, .. }) => {
            assert_eq!(found, "6.0.0");
            assert_eq!(expected, ["7.1.0-dev.20260926.1"].as_slice());
        }
        Err(other) => panic!("expected UnsupportedVersion, got {other:?}"),
        Ok(_) => panic!("expected UnsupportedVersion, but spawn succeeded"),
    }
}

#[tokio::test]
async fn an_unreadable_package_json_is_reported_distinctly() {
    let dir = tempfile::tempdir().expect("temp dir");
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    std::fs::create_dir_all(typescript_dir.join("bin")).expect("create dirs");
    // No package.json written at all.
    let tsc_path = camino::Utf8PathBuf::from_path_buf(typescript_dir.join("bin").join("tsc")).expect("utf8");
    let cwd = camino::Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("utf8");
    let config = SupervisorConfig::new(tsc_path, cwd, &[common::PINNED_VERSION]);

    match Supervisor::spawn(config).await {
        Err(TscClientError::VersionCheckFailed { .. }) => {}
        Err(other) => panic!("expected VersionCheckFailed, got {other:?}"),
        Ok(_) => panic!("expected VersionCheckFailed, but spawn succeeded"),
    }
}
use std::sync::Arc;
use std::time::Duration;

use camino::Utf8PathBuf;

/// One variant family per Lifecycle-gate item (docs/type-checker-integration.md,
/// "Gates before it ships") so a caller or test can tell failure modes apart.
///
/// `Clone` on purpose, not just for this crate's own internal fan-out (one session-
/// ending failure delivered to every pending caller — see `Client::fail_all_pending`):
/// a caller-facing error type that can't be cloned forces callers to choose between
/// logging it and propagating it. The only non-`Clone` sources are `io::Error` and
/// `serde_json::Error`, `Arc`-wrapped below so cloning the rare error path is just a
/// refcount bump, never a real cost on the common (success) path.
#[derive(Debug, Clone, thiserror::Error)]
#[non_exhaustive]
pub enum TscClientError {
    #[error("tsc binary not found at {path} — install `typescript@next` (npm i typescript@next) or pass an explicit path ({source})")]
    SpawnFailed {
        path: Utf8PathBuf,
        #[source]
        source: Arc<std::io::Error>,
    },

    #[error("tsc at {path} reports version {found:?}, not pinned (expected one of {expected:?})")]
    UnsupportedVersion { path: Utf8PathBuf, found: String, expected: &'static [&'static str] },

    #[error("could not determine tsc's version at {path}: {reason}")]
    VersionCheckFailed { path: Utf8PathBuf, reason: String },

    #[error("request {method:?} timed out after {after:?}")]
    Timeout { method: String, after: Duration },

    #[error("tsc exited unexpectedly (status: {status:?})")]
    Crashed { status: Option<std::process::ExitStatus> },

    #[error("tsc restarted {attempts} times within {window:?}; treating as permanently failed")]
    RestartStormDetected { attempts: u32, window: Duration },

    #[error("oversized frame: declared Content-Length {declared} exceeds the {cap}-byte cap")]
    OversizedFrame { declared: usize, cap: usize },

    #[error("malformed frame: {reason:?}")]
    MalformedFrame { reason: MalformedFrameReason },

    #[error("tsc returned a JSON-RPC error (code {code}): {message}")]
    RpcError { code: i64, message: String, data: Option<serde_json::Value> },

    #[error("session already shut down or permanently failed")]
    SessionClosed,

    #[error("I/O error writing to tsc: {0}")]
    Write(#[source] Arc<std::io::Error>),

    #[error("I/O error reading from tsc: {0}")]
    Read(#[source] Arc<std::io::Error>),

    #[error("failed to serialize a request: {0}")]
    Serialize(#[source] Arc<serde_json::Error>),

    #[error("failed to reap tsc's process: {0}")]
    Reap(#[source] Arc<std::io::Error>),
}

