mod common;

use std::os::unix::fs::PermissionsExt;
use std::time::{Duration, Instant};

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};

fn short(r: &Result<oxc_react_docgen_tsc_client::TaggedResponse, TscClientError>) -> String {
    match r {
        Ok(t) => format!("Ok(seq={}, value={})", t.seq, t.value),
        Err(e) => format!("Err({e:?})").chars().take(160).collect(),
    }
}

#[tokio::test]
async fn probe_spawn_failure_during_restart() {
    let (dir, config) = common::spawn_fake("exit_after:1:7");
    let pkg = dir.path().join("node_modules/typescript/package.json");
    let mut sup = Supervisor::spawn(config).await.unwrap();
    eprintln!("A req1 {}", short(&sup.request("a", serde_json::json!({}), Duration::from_secs(2)).await));
    tokio::time::sleep(Duration::from_millis(100)).await;
    // Simulate `npm i typescript@next` landing a new build between calls.
    std::fs::write(&pkg, r#"{"version": "7.2.0"}"#).unwrap();
    for i in 2..=6 {
        let t = Instant::now();
        let r = sup.request("q", serde_json::json!({}), Duration::from_secs(2)).await;
        eprintln!("A req{i} after {:?} alive={} {}", t.elapsed(), sup.is_alive(), short(&r));
    }
    std::fs::write(&pkg, format!(r#"{{"version": "{}"}}"#, common::PINNED_VERSION)).unwrap();
    let r = sup.request("q", serde_json::json!({}), Duration::from_secs(2)).await;
    eprintln!("A after restoring version: {}", short(&r));
}

#[tokio::test]
async fn probe_recovery_before_cap() {
    let (dir, config) = common::spawn_fake("exit_after:1:7");
    let pkg = dir.path().join("node_modules/typescript/package.json");
    let mut sup = Supervisor::spawn(config).await.unwrap();
    eprintln!("B req1 {}", short(&sup.request("a", serde_json::json!({}), Duration::from_secs(2)).await));
    tokio::time::sleep(Duration::from_millis(100)).await;
    std::fs::write(&pkg, r#"{"version": "7.2.0"}"#).unwrap();
    eprintln!("B req2 {}", short(&sup.request("q", serde_json::json!({}), Duration::from_secs(2)).await));
    std::fs::write(&pkg, format!(r#"{{"version": "{}"}}"#, common::PINNED_VERSION)).unwrap();
    eprintln!("B req3 {}", short(&sup.request("q", serde_json::json!({}), Duration::from_secs(2)).await));
}

fn script_layout(dir: &tempfile::TempDir, body: &str) -> SupervisorConfig {
    let ts = dir.path().join("node_modules/typescript");
    std::fs::create_dir_all(ts.join("bin")).unwrap();
    std::fs::write(ts.join("package.json"), format!(r#"{{"version": "{}"}}"#, common::PINNED_VERSION)).unwrap();
    let tsc = ts.join("bin/tsc");
    std::fs::write(&tsc, body).unwrap();
    std::fs::set_permissions(&tsc, std::fs::Permissions::from_mode(0o755)).unwrap();
    SupervisorConfig::new(
        Utf8PathBuf::from_path_buf(tsc).unwrap(),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap(),
        &[common::PINNED_VERSION],
    )
}

#[tokio::test]
async fn probe_fatal_frame_with_live_child_never_restarts() {
    let dir = tempfile::tempdir().unwrap();
    let count = dir.path().join("spawns");
    let body = format!(
        "#!/bin/sh\necho x >> '{}'\nprintf 'Content-Length: 999999999\\r\\n\\r\\n'\nexec cat > /dev/null\n",
        count.display()
    );
    let config = script_layout(&dir, &body);
    let mut sup = Supervisor::spawn(config).await.unwrap();
    tokio::time::sleep(Duration::from_millis(200)).await;
    eprintln!("C alive after bad header: {}", sup.is_alive());
    for i in 1..=4 {
        let t = Instant::now();
        let r = sup.request("q", serde_json::json!({}), Duration::from_millis(300)).await;
        eprintln!("C req{i} after {:?} {}", t.elapsed(), short(&r));
    }
    let spawns = std::fs::read_to_string(&count).unwrap().lines().count();
    eprintln!("C spawn count = {spawns}");
    sup.shutdown().await.unwrap();
}

#[tokio::test]
async fn probe_replay_after_mid_request_crash() {
    let dir = tempfile::tempdir().unwrap();
    let count = dir.path().join("count");
    let seen = dir.path().join("seen");
    let fake = env!("CARGO_BIN_EXE_fake-tsc");
    let body = format!(
        "#!/bin/sh\nn=$(cat '{c}' 2>/dev/null || echo 0); n=$((n+1)); echo $n > '{c}'\nif [ $n -eq 1 ]; then\n  exec '{f}'\nfi\nif [ $n -eq 2 ]; then head -c 40 >> '{s}'; exit 1; fi\nexec '{f}'\n",
        c = count.display(),
        s = seen.display(),
        f = fake
    );
    let mut config = script_layout(&dir, &body);
    // Process 1: `exit_after:2:7` answers two requests then exits.
    config.extra_env.push(("FAKE_TSC_SCENARIO".into(), "exit_after:2:7".into()));
    let mut sup = Supervisor::spawn(config).await.unwrap();
    let a = sup.request("updateSnapshot", serde_json::json!({}), Duration::from_secs(2)).await;
    let b = sup.request("getSymbol", serde_json::json!({"snapshot": 1}), Duration::from_secs(2)).await;
    eprintln!("D a={} b={}", short(&a), short(&b));
    tokio::time::sleep(Duration::from_millis(100)).await;
    // Process 1 is dead; restart spawns process 2 which crashes; the retry's error is returned.
    let c = sup.request("getTypeOfSymbol", serde_json::json!({"snapshot": 1, "symbol": 42}), Duration::from_secs(2)).await;
    eprintln!("D c={}", short(&c));
    // Next call: process 2 received (part of) c's replay then died; process 3 gets d replayed.
    let d = sup.request("getTypeOfSymbol", serde_json::json!({"snapshot": 1, "symbol": 42}), Duration::from_secs(2)).await;
    eprintln!("D d={}", short(&d));
    eprintln!("D process2 saw: {:?}", std::fs::read_to_string(&seen).unwrap_or_default());
    eprintln!("D spawns = {}", std::fs::read_to_string(&count).unwrap().trim());
}

